SourceCode.Declaration:
/// <summary>
/// A batch and its quantity on a transfer line - see HSMobileOpsTransferLineContract.parmShippedBatches.
/// </summary>
[DataContractAttribute]
class HSMobileOpsTransferBatchRow
{
    InventBatchId batchId;
    InventQty     qty;
}

Method.Source:
[DataMemberAttribute('BatchId')]
public InventBatchId parmBatchId(InventBatchId _value = batchId)
{
    batchId = _value;
    return batchId;
}

[DataMemberAttribute('Qty')]
public InventQty parmQty(InventQty _value = qty)
{
    qty = _value;
    return qty;
}
